'use strict';
const $=s=>document.querySelector(s), key=new URLSearchParams(location.search).has('budget')?'pocket-budget-v1-'+new URLSearchParams(location.search).get('budget'):(new URLSearchParams(location.search).get('example')==='marcus'?'pocket-marcus-test-v1':'pocket-budget-v1');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, cents=n=>Math.round(Number(n)*100), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), date=s=>new Date(s+'T12:00:00'), days=s=>Math.round((date(s)-date(today()))/86400000), pretty=s=>date(s).toLocaleDateString('en-US',{month:'short',day:'numeric'});
let state={ready:false,opening:0,saved:0,goal:'',target:0,payAmount:0,payDate:'',payFrequency:'weekly',transactions:[],costs:[]}, mode='', storageOkay=true, memoryOnly=false, dataLoadBlocked=false;
try{memoryOnly=localStorage.getItem(key+'-no-save')==='1';const raw=memoryOnly?null:localStorage.getItem(key);if(raw){const parsed=validateBudget(JSON.parse(raw));if(!Array.isArray(parsed.transactions)||!Array.isArray(parsed.costs))throw Error();state={...state,...parsed};}}catch{storageOkay=false;dataLoadBlocked=true;}
// Upgrade old one-goal budgets without losing their saved money.
if(!Array.isArray(state.goals))state.goals=state.goal||state.saved?[{id:uid(),name:state.goal||'Savings',target:state.target||state.saved,saved:state.saved}]:[];
function syncSavings(){state.saved=state.goals.reduce((n,g)=>n+g.saved,0)}
syncSavings();
let selectedGoal='',pendingSnapshot=null,lastUndo=null;
function persist(){if(memoryOnly)return true;if(dataLoadBlocked)return false;try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{storageOkay=false;return false;}}
function notify(message){$('#notice').textContent=message;}
function total(){return state.opening+state.transactions.reduce((a,t)=>a+(t.type==='in'?t.amount:t.type==='out'?-t.amount:0),0)}
function owed(){return state.costs.reduce((a,c)=>a+c.amount,0)}
function available(){return total()-state.saved-owed()}
function advance(s,f){let d=date(s);if(f==='monthly'){let day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));}else d.setDate(d.getDate()+(f==='weekly'?7:14));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function record(type,amount,title,when=today(),extra={}){state.transactions.push({id:uid(),type,amount,title,date:when,...extra})}
function finish(message){lastUndo=pendingSnapshot;pendingSnapshot=null;$('#undo').hidden=!lastUndo;document.body.classList.remove('onboarding');const ok=persist();render();$('#modal').close();notify(ok?message:message+' Browser storage is unavailable; keep this page open or your changes will be lost.');}
function activity(t){const sign=t.type==='in'?'+':t.type==='out'?'−':t.type==='save'?'↗':'↙';return `<div class="row"><span class="row-icon">${sign}</span><div class="row-info"><b>${esc(t.title)}</b><small>${pretty(t.date)} · ${{in:'Money in',out:'Money out',save:'Moved into savings',unsave:'Moved out of savings'}[t.type]}</small></div><span class="row-amount ${t.type==='in'?'positive':''}">${sign} ${money(t.amount)}</span></div>`}
function costRow(c,actions=false){let d=days(c.date),label=d<0?`${-d} day${d===-1?'':'s'} overdue`:d===0?'Due today':d===1?'Due tomorrow':pretty(c.date);return `<div class="row"><span class="row-icon">${c.frequency==='once'?'◷':'↻'}</span><div class="row-info"><b>${esc(c.title)}</b><small>${esc(c.kind)} · ${c.frequency==='once'?'One time':c.frequency}</small></div><span class="row-amount">${money(c.amount)}<small>${label}</small></span>${actions?`<div class="cost-actions"><button class="secondary" data-pay="${esc(c.id)}">Mark paid</button><button class="text-button" data-remove="${esc(c.id)}">Remove</button></div>`:''}</div>`}
function render(){
$('#today').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#total').textContent=money(total());$('#available').textContent=money(Math.abs(available()));$('#available-label').textContent=available()<0?'Short for upcoming costs':'Available to spend';$('#reserved').textContent=money(state.saved);$('#balance-note').textContent=available()<0?`You have ${money(total())} cash, with ${money(owed())} unpaid costs and ${money(state.saved)} saved.`:`After ${money(state.saved)} savings + ${money(owed())} unpaid costs.`;
let start=date(today());start.setDate(start.getDate()-((start.getDay()+6)%7));let week=state.transactions.filter(t=>t.date<=today());$('#income').textContent=money(week.filter(t=>t.type==='in').reduce((a,t)=>a+t.amount,0));$('#spent').textContent=money(week.filter(t=>t.type==='out').reduce((a,t)=>a+t.amount,0));
$('#payday').textContent=state.payDate?(days(state.payDate)<0?'Check in':days(state.payDate)===0?'Today':`In ${days(state.payDate)} days`):'Not set';$('#pay-caption').textContent=state.payDate?`${money(state.payAmount)} expected · ${pretty(state.payDate)}`:'Add your next income in setup';$('#received').hidden=!state.payDate;
$('#goals').innerHTML=state.goals.map(g=>{let pct=g.target?Math.min(100,Math.round(g.saved/g.target*100)):0;return '<section class="goal-tile visual-goal"><div class="jar-visual" role="img" aria-label="'+esc(g.name)+': '+money(g.saved)+' of '+money(g.target)+', '+pct+' percent saved"><div class="jar-lid"></div><div class="savings-jar"><div class="coin-fill" style="height:'+pct+'%"></div><span class="jar-tape">'+pct+'%</span></div></div><div class="goal-details"><div class="section-head"><h3>'+esc(g.name)+'</h3><button class="text-button" data-goal-edit="'+esc(g.id)+'" aria-label="Edit '+esc(g.name)+'">Edit</button></div><div class="goal-amount"><strong>'+money(g.saved)+'</strong><span>of '+money(g.target)+'</span><b>'+pct+'%</b></div><progress value="'+pct+'" max="100" aria-label="'+esc(g.name)+' progress"></progress><div class="quick-actions"><button class="secondary" data-goal-save="'+esc(g.id)+'">＋ Add</button><button class="text-button" data-goal-unsave="'+esc(g.id)+'" '+(g.saved?'':'disabled')+'>Take out</button><span class="muted small">'+(g.saved>=g.target?'Goal reached!':money(g.target-g.saved)+' to go')+'</span></div></div></section>'}).join('')||'<div class="empty-jar" aria-hidden="true">◡</div><p class="empty">Your next plan starts with an empty jar.<br>Add a goal for whatever matters to you.</p>';

const spendingGroups=new Map();for(const t of state.transactions.filter(t=>t.type==='out')){const name=t.title||'Spending';spendingGroups.set(name,(spendingGroups.get(name)||0)+t.amount)}
let grouped=[...spendingGroups].sort((a,b)=>b[1]-a[1]);const spentTotal=grouped.reduce((n,row)=>n+row[1],0);if(grouped.length>4)grouped=[...grouped.slice(0,4),['Other purchases',grouped.slice(4).reduce((n,row)=>n+row[1],0)]];
$('#spending-picture').innerHTML=spentTotal?'<div class="spending-total">'+money(spentTotal)+'<span> spent in total</span></div>'+grouped.map(([name,value],i)=>'<div class="spend-item"><div class="spend-label"><span>'+esc(name)+'</span><b>'+money(value)+'</b></div><div class="spend-track" role="img" aria-label="'+esc(name)+': '+money(value)+', '+Math.round(value/spentTotal*100)+' percent of recorded spending"><div class="spend-fill shade-'+i+'" style="width:'+value/spentTotal*100+'%"></div></div><small>'+Math.round(value/spentTotal*100)+'% of spending</small></div>').join(''):'<div class="spending-empty"><span aria-hidden="true">↗</span><h3>A fresh start</h3><p class="muted">Log a purchase and see where your money goes.<br>No sample spending here.</p><button class="secondary" id="visual-log">Log spending</button></div>';
if($('#visual-log'))$('#visual-log').onclick=()=>openModal('transaction');
let costs=[...state.costs].sort((a,b)=>a.date.localeCompare(b.date));$('#upcoming-short').innerHTML=costs.slice(0,3).map(c=>costRow(c)).join('')||'<p class="empty">Nothing coming up yet. Add subscriptions, bills, or money you owe.</p>';let cf=$('#cost-filter').value;let visibleCosts=costs.filter(c=>cf==='month'?c.date.slice(0,7)===today().slice(0,7):cf==='soon'?days(c.date)<=7:cf==='owed'?c.kind==='Money I owe':true);$('#cost-summary').textContent=`${visibleCosts.length} unpaid · ${money(visibleCosts.reduce((n,c)=>n+c.amount,0))}`;$('#cost-list').innerHTML=visibleCosts.map(c=>costRow(c,true)).join('')||'<p class="empty">You’re all caught up. No unpaid costs.</p>';
let tx=[...state.transactions].reverse().sort((a,b)=>b.date.localeCompare(a.date));$('#recent').innerHTML=tx.slice(0,5).map(activity).join('')||'<p class="empty">A fresh start. Log some money to see your activity here.</p>';let f=$('#filter').value;$('#history-list').innerHTML=tx.filter(t=>f==='all'||(f==='save'?['save','unsave'].includes(t.type):t.type===f)).map(activity).join('')||'<p class="empty">No activity here yet.</p>';$('#paid-list').innerHTML=tx.filter(t=>t.costId).map(activity).join('')||'<p class="empty">Costs you mark paid will appear here.</p>';
let chart=[];for(let i=6;i>=0;i--){let d=date(today());d.setDate(d.getDate()-i);let dt=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let ts=state.transactions.filter(t=>t.date===dt);chart.push({label:d.toLocaleDateString('en-US',{weekday:'short'}),out:ts.filter(t=>t.type==='out').reduce((a,t)=>a+t.amount,0),saved:ts.filter(t=>t.type==='save').reduce((a,t)=>a+t.amount,0)});}let max=Math.max(100,...chart.flatMap(c=>[c.out,c.saved]));$('#chart').innerHTML=chart.map(c=>`<div class="day" title="${c.label}: spent ${money(c.out)}, saved ${money(c.saved)}"><div class="bars"><div class="bar" style="height:${c.out/max*100}%"></div><div class="bar saving" style="height:${c.saved/max*100}%"></div></div><span class="day-label">${c.label}</span></div>`).join('');
}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const amount=(label,name,value='',required=true)=>field(label,name,'number',value,`min="${required?'0.01':'0'}" max="1000000" step="0.01" ${required?'required':''}`);
function openModal(kind,preset=''){pendingSnapshot=null;mode=kind;$('#error').textContent='';$('#close').hidden=state.surveyVersion!==2;$('#modal-kicker').textContent=kind==='setup'?'YOUR MONEY STARTS HERE':'ONE SMALL STEP';let title='',desc='',html='',submit='Save';
if(kind==='setup'){const reviewed=state.surveyVersion===2;title=reviewed?'Your money setup':'Hey, welcome to Pocket.';desc='Tell us what you actually have. Your answers set every starting number. Only your current total is required. Everything else is optional. If you add income, include its date. If you add a goal, include its price. Nothing is estimated.';html=amount('Current total money ($), including savings — required','opening',reviewed?total()/100:'',false).replace('min="0"','required min="0"')+'<div class="form-grid">'+amount('Next income ($) — optional','payAmount',reviewed&&state.payAmount?state.payAmount/100:'',false)+field('When will it arrive? — optional','payDate','date',reviewed?state.payDate:'')+'</div><label>How often? — optional<select name="payFrequency"><option value="weekly">Every week</option><option value="fortnightly">Every 2 weeks</option><option value="monthly">Every month</option><option value="once">Just once</option></select></label>';if(!reviewed)html+=field('What are you saving for? (optional)','goal','text',reviewed?state.goal:'','maxlength="70"')+'<div class="form-grid">'+amount('Goal price ($) — optional','target',reviewed&&state.target?state.target/100:'',false)+amount('Already set aside ($) — optional','saved',reviewed?state.saved/100:'',false)+'</div>';submit=reviewed?'Update setup':'Let’s see my money →';}
if(kind==='transaction'){const incoming=preset==='in';title=incoming?'Money in':'Quick spending';desc='Amount. Save. Done.';html='<input type="hidden" name="type" value="'+(incoming?'in':'out')+'">'+amount('Amount ($)','amount')+field('Note (optional)','title','text','','maxlength="80" placeholder="Food, travel, books, anything…"')+'<details class="extra-details"><summary>Today · change date</summary>'+field('Date','date','date',today(),'required max="'+today()+'"')+'</details>';submit=incoming?'Add money':'Save spending';}
if(kind==='cost'){title='Let’s plan for it.';desc='Add a subscription, a cost coming up, or money you owe.';html=field('What’s the cost?','title','text','','required maxlength="80" placeholder="Membership, transport, tuition…"')+'<div class="form-grid">'+amount('Amount ($)','amount')+field('Due date','date','date',today(),'required')+'</div><label>Type<select name="kind"><option>Upcoming cost</option><option>Subscription</option><option>Money I owe</option></select></label><label>Repeats<select name="frequency"><option value="once">Doesn’t repeat</option><option value="weekly">Weekly</option><option value="fortnightly">Every 2 weeks</option><option value="monthly">Monthly</option></select></label>';submit='Add cost';}
if(kind==='goal'){const g=state.goals.find(g=>g.id===preset);selectedGoal=g?.id||'';title=g?'Edit goal':'What are you saving for?';desc='Your plans, big or small.';html=field('Goal name','goal','text',g?.name||'','required maxlength="70" placeholder="Concert, camera, books…"')+amount('Target ($)','target',g?g.target/100:'');submit=g?'Save changes':'Create goal';}
if(kind==='save'||kind==='unsave'){const g=state.goals.find(g=>g.id===preset);if(!g)return;selectedGoal=g.id;title=kind==='save'?'Add to '+g.name:'Take out of '+g.name;desc=kind==='save'?money(Math.max(0,available()))+' available after planned costs.':money(g.saved)+' saved. This moves money back to spending.';html=amount('Amount ($)','amount');submit=kind==='save'?'Add to goal':'Take out';}
$('#modal-title').textContent=title;$('#modal-desc').textContent=desc;$('#fields').innerHTML=html;$('#submit').textContent=submit;if(kind==='setup')$('[name="payFrequency"]').value=state.payFrequency;if(kind==='transaction'&&preset)$('[name="type"]').value=preset;if(kind==='cost'&&preset){$('[name="kind"]').value=preset;$('[name="frequency"]').value=preset==='Subscription'?'monthly':'once';}$('#modal').showModal();if(['transaction','save','unsave'].includes(kind))$('[name="amount"]').focus();else if(kind==='goal')$('[name="goal"]').focus();}
$('#form').addEventListener('submit',e=>{e.preventDefault();pendingSnapshot=JSON.stringify(state);let d=Object.fromEntries(new FormData(e.target));const fail=m=>{$('#error').textContent=m;};let a=cents(d.amount||0);
if(mode==='setup'){let opening=cents(d.opening||0),saved=state.surveyVersion===2?state.saved:cents(d.saved||0),target=cents(d.target||0);if(saved>opening)return fail('Savings must be part of the money you already have.');if(state.surveyVersion!==2&&saved>0&&(!d.goal||!target))return fail('Add a goal name and price for your saved money.');if(d.goal&&!target)return fail('Add a price for your goal.');if((cents(d.payAmount||0)>0)!==Boolean(d.payDate))return fail('Enter both the income amount and its date, or leave both empty.');if(state.ready&&state.transactions.length>0){let delta=opening-total();if(delta)record(delta>0?'in':'out',Math.abs(delta),'Balance check-in');}else{state.opening=opening;state.saved=saved;state.goal=d.goal;state.target=target;}if(state.surveyVersion!==2)state.goals=d.goal?.trim()?[{id:uid(),name:d.goal.trim(),target,saved}]:[];syncSavings();Object.assign(state,{ready:true,surveyVersion:2,payAmount:cents(d.payAmount||0),payDate:d.payDate,payFrequency:d.payFrequency});finish('Your money picture is up to date.');if(typeof offerTutorial==='function')offerTutorial();}
else if(mode==='transaction'){if(d.date>today())return fail('Use today or an earlier date. Add future payments under Upcoming.');if(d.type==='out'&&a>total()-state.saved)return fail('That is more than your money outside savings. Move savings back first, or check your balance.');if(!Number.isSafeInteger(a)||a<=0)return fail('Enter an amount greater than zero.');record(d.type,a,d.title?.trim()||(d.type==='in'?'Money received':'Spending'),d.date||today());finish('Logged. Your totals are updated.');}
else if(mode==='cost'){state.costs.push({...d,amount:a,title:d.title.trim(),id:uid()});finish('Cost added. Your available money now accounts for it.');}
else if(mode==='goal'){const name=d.goal.trim(),target=cents(d.target);if(!name||!Number.isSafeInteger(target)||target<=0)return fail('Add a name and a target greater than zero.');let g=state.goals.find(g=>g.id===selectedGoal);if(g){g.name=name;g.target=target;}else state.goals.push({id:uid(),name,target,saved:0});finish('Goal saved.');}
else if(mode==='save'||mode==='unsave'){const g=state.goals.find(g=>g.id===selectedGoal);if(!g)return fail('Choose a goal first.');if(!Number.isSafeInteger(a)||a<=0)return fail('Enter an amount greater than zero.');if(mode==='save'&&a>Math.max(0,available()))return fail('That is more than your available money.');if(mode==='unsave'&&a>g.saved)return fail('That is more than this goal has saved.');g.saved+=mode==='save'?a:-a;syncSavings();record(mode,a,(mode==='save'?'Saved for ':'Took out of ')+g.name,today(),{goalId:g.id});finish(mode==='save'?'Saved. A little closer.':'Moved back to spending.');}});

document.addEventListener('click',e=>{for(const [attr,kind] of [['goal-edit','goal'],['goal-save','save'],['goal-unsave','unsave']]){const button=e.target.closest('[data-'+attr+']');if(button){openModal(kind,button.getAttribute('data-'+attr));return;}}const v=e.target.closest('[data-view]');if(v){document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==v.dataset.view);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v.dataset.view));}const p=e.target.closest('[data-pay]');if(p){const c=state.costs.find(x=>x.id===p.dataset.pay);if(!c)return;if(c.amount>total()-state.saved){notify('Not enough money outside savings. Update your money or move savings back first.');return;}if(!confirm(`Record ${money(c.amount)} paid for ${c.title}?`))return;record('out',c.amount,c.title,today(),{costId:c.id});if(c.frequency==='once')state.costs=state.costs.filter(x=>x.id!==c.id);else c.date=advance(c.date,c.frequency);finish('Payment logged. '+(c.frequency!=='once'?'The next charge is now listed.':''));}const r=e.target.closest('[data-remove]');if(r&&confirm('Remove this planned cost? This does not record a payment.')){state.costs=state.costs.filter(c=>c.id!==r.dataset.remove);finish('Planned cost removed.');}});
$('#add').onclick=$('#weekly').onclick=()=>openModal('transaction');$('#settings').onclick=()=>openModal('setup');$('#add-cost').onclick=$('#new-cost').onclick=()=>openModal('cost');$('#new-goal').onclick=()=>openModal('goal');$('#undo').onclick=()=>{if(!lastUndo)return;state=JSON.parse(lastUndo);lastUndo=null;pendingSnapshot=null;syncSavings();const ok=persist();render();$('#undo').hidden=true;notify(ok?'Undone.':'Undone, but browser storage is unavailable.');};$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('cancel',e=>{if(state.surveyVersion!==2)e.preventDefault();});$('#filter').onchange=render;$('#cost-filter').onchange=render;$('#add-subscription').onclick=()=>openModal('cost','Subscription');$('#add-debt').onclick=()=>openModal('cost','Money I owe');$('#received').onclick=()=>{if(!confirm(`Have you actually received ${money(state.payAmount)}?`))return;record('in',state.payAmount,'Income received');if(state.payFrequency==='once')state.payDate='';else state.payDate=advance(state.payDate,state.payFrequency);finish('Income logged. Your next money day is updated.');};render();if(!storageOkay)notify('Saved data could not be safely loaded. The original has not been overwritten. Use Privacy to delete it only if you want to start again.');if(state.surveyVersion!==2&&!dataLoadBlocked){document.body.classList.add('onboarding');openModal('setup');}





